import{f as c,D as l,o,c as p,a2 as i,b as r,w as e,a as s,G as d,a5 as n}from"./chunks/framework.Cd9rfTEn.js";const C=JSON.parse('{"title":"GoodApps Cooperativas","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/01-resumen-ejecutivo-vision.md","filePath":"entregables-analisis-diseno/01-resumen-ejecutivo-vision.md","lastUpdated":null}'),u={name:"entregables-analisis-diseno/01-resumen-ejecutivo-vision.md"};function m(g,a,b,v,f,y){const t=l("Mermaid");return o(),p("div",null,[a[2]||(a[2]=i('<h1 id="goodapps-cooperativas" tabindex="-1">GoodApps Cooperativas <a class="header-anchor" href="#goodapps-cooperativas" aria-label="Permalink to &quot;GoodApps Cooperativas&quot;">​</a></h1><h2 id="resumen-ejecutivo-y-vision-del-proyecto" tabindex="-1">Resumen ejecutivo y visión del proyecto <a class="header-anchor" href="#resumen-ejecutivo-y-vision-del-proyecto" aria-label="Permalink to &quot;Resumen ejecutivo y visión del proyecto&quot;">​</a></h2><p><strong>Entregable de Análisis y Diseño Detallado — Artefacto 1.3 (Visión y alcance)</strong></p><table tabindex="0"><thead><tr><th>Dato</th><th>Valor</th></tr></thead><tbody><tr><td>Producto</td><td>GoodApps Cooperativas: plataforma de gestión en la nube (SaaS multi-tenant) para cooperativas de servicios públicos y sociales</td></tr><tr><td>Documento</td><td>Resumen ejecutivo y visión</td></tr><tr><td>Destinatarios</td><td>Consejo de administración, gerencia y responsables de área de la cooperativa</td></tr><tr><td>Carácter</td><td>Documento derivado de la especificación vigente; no la reemplaza. Ante cualquier diferencia prevalecen la especificación maestra (<code>00</code>), sus anexos y el registro de decisiones (<code>01</code>)</td></tr><tr><td>Versión</td><td>1.0</td></tr><tr><td>Fecha</td><td>05-11-2026</td></tr></tbody></table><h3 id="control-de-versiones" tabindex="-1">Control de versiones <a class="header-anchor" href="#control-de-versiones" aria-label="Permalink to &quot;Control de versiones&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Versión</th><th>Fecha</th><th>Descripción del cambio</th><th>Autor</th></tr></thead><tbody><tr><td>1.0</td><td>05-11-2026</td><td>Versión inicial del resumen ejecutivo y visión</td><td></td></tr></tbody></table><h3 id="aprobaciones" tabindex="-1">Aprobaciones <a class="header-anchor" href="#aprobaciones" aria-label="Permalink to &quot;Aprobaciones&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rol</th><th>Nombre</th><th>Firma</th><th>Fecha</th></tr></thead><tbody><tr><td>Elaboró</td><td></td><td></td><td></td></tr><tr><td>Revisó</td><td></td><td></td><td></td></tr><tr><td>Aprobó</td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="indice" tabindex="-1">Índice <a class="header-anchor" href="#indice" aria-label="Permalink to &quot;Índice&quot;">​</a></h2><ol><li>Propósito del documento</li><li>Contexto y problema</li><li>Visión y propuesta de valor</li><li>Objetivos de negocio medibles</li><li>Alcance</li><li>Fuera de alcance</li><li>Usuarios y actores</li><li>Beneficios esperados por actor</li><li>Enfoque de implementación</li><li>Principales decisiones tomadas</li><li>Riesgos principales y mitigación</li><li>Supuestos y dependencias</li><li>Próximos pasos y validaciones pendientes</li><li>Documentos de referencia</li></ol><hr><h2 id="_1-proposito-del-documento" tabindex="-1">1. Propósito del documento <a class="header-anchor" href="#_1-proposito-del-documento" aria-label="Permalink to &quot;1. Propósito del documento&quot;">​</a></h2><p>Este documento presenta, en lenguaje de negocio, <strong>qué es GoodApps Cooperativas, por qué se construye, qué incluye, cómo se va a implementar y cuáles son sus riesgos y decisiones principales</strong>. Está dirigido a los directivos y a la gerencia de la cooperativa, que necesitan una visión integral para evaluar el proyecto, tomar decisiones y aprobar los próximos pasos sin entrar en el detalle técnico.</p><p>Es el artefacto 1.3 del índice de entregables de análisis y diseño (<code>00-INDICE.md</code>). Resume y reorganiza el contenido de la especificación del sistema, que está compuesta por un documento maestro, 31 anexos funcionales y técnicos, un registro de decisiones, un registro de preguntas abiertas, un plan de construcción por olas, una matriz de trazabilidad y un registro de huecos de cobertura. Este resumen <strong>no agrega requisitos nuevos</strong>: cuando se cita un dato, se indica su fuente; cuando un valor no figura en la especificación, se marca expresamente como <strong>&quot;a definir&quot;</strong>.</p><p>El documento sirve para:</p><ul><li>alinear a la conducción de la cooperativa sobre la visión y el alcance del producto;</li><li>dar a conocer las decisiones ya tomadas y las que quedan pendientes de validación;</li><li>identificar los riesgos principales y su tratamiento;</li><li>acordar los próximos pasos, en particular la formalización con Laguna Larga como cooperativa piloto y las validaciones legales.</li></ul><hr><h2 id="_2-contexto-y-problema" tabindex="-1">2. Contexto y problema <a class="header-anchor" href="#_2-contexto-y-problema" aria-label="Permalink to &quot;2. Contexto y problema&quot;">​</a></h2><p>Las cooperativas de servicios públicos de la Argentina prestan, en muchos casos, varios servicios a la vez: electricidad, agua, cloacas, gas, Internet, telefonía, televisión, sepelio, salud, vivienda y otros servicios sociales. Hoy gran parte de ellas opera con <strong>ProCoop</strong>, un sistema de gestión de escritorio. El relevamiento de ese sistema (documentado en la base funcional y en la especificación maestra §1.1 y §4.4) muestra un conjunto de limitaciones que, traducidas a términos de negocio, son las siguientes.</p><table tabindex="0"><thead><tr><th>Limitación del sistema actual</th><th>Consecuencia para la cooperativa</th></tr></thead><tbody><tr><td>Instalación local en cada computadora y actualizaciones manuales</td><td>Costos y tiempos de mantenimiento propios; versiones desparejas entre puestos; dependencia de personal técnico para cada actualización.</td></tr><tr><td>Una base de datos separada por cooperativa, administrada localmente</td><td>La cooperativa debe ocuparse de servidores, copias de seguridad y recuperación ante fallas; el riesgo de pérdida de información queda a su cargo.</td></tr><tr><td>Seguridad débil: contraseñas que pueden descifrarse, un usuario de base de datos compartido y credenciales escritas dentro del programa</td><td>Exposición de datos de socios y de credenciales fiscales y bancarias; dificultad para saber quién hizo cada operación.</td></tr><tr><td>Más de 1.500 parámetros (1.536) identificados con números sin significado</td><td>La configuración depende de pocas personas que conocen los códigos; cualquier cambio de tarifa, concepto o política es riesgoso y difícil de auditar.</td></tr><tr><td>Integraciones frágiles con organismos, bancos, entes recaudadores y equipos de red</td><td>Errores en cobranzas, rendiciones y autorizaciones fiscales; tareas manuales de corrección y conciliación.</td></tr><tr><td>Portal del socio que funciona sobre una copia sincronizada de los datos</td><td>Información desactualizada para el socio, experiencia digital limitada y doble mantenimiento.</td></tr><tr><td>Experiencia digital casi nula para el socio y para el personal de campo</td><td>Mayor carga en mostrador y teléfono; trabajo de campo en papel o con herramientas aisladas; menor velocidad para cobrar, atender y resolver.</td></tr></tbody></table><p>Además, las cooperativas enfrentan un entorno cada vez más exigente: facturación electrónica obligatoria, múltiples regímenes impositivos nacionales, provinciales y municipales, informes a entes reguladores, protección de datos personales (Ley 25.326) y socios que esperan resolver sus trámites desde el celular. El sistema actual no fue concebido para ese escenario.</p><hr><h2 id="_3-vision-y-propuesta-de-valor" tabindex="-1">3. Visión y propuesta de valor <a class="header-anchor" href="#_3-vision-y-propuesta-de-valor" aria-label="Permalink to &quot;3. Visión y propuesta de valor&quot;">​</a></h2><h3 id="_3-1-vision" tabindex="-1">3.1 Visión <a class="header-anchor" href="#_3-1-vision" aria-label="Permalink to &quot;3.1 Visión&quot;">​</a></h3><blockquote><p>Brindar a cada cooperativa una plataforma única, segura y configurable que le permita administrar de punta a punta todos sus servicios, su relación con los socios y su gestión interna, con información confiable, trazable y disponible en cualquier momento y lugar.</p><p><em>(Documento de alcance funcional, §2.1)</em></p></blockquote><h3 id="_3-2-propuesta-de-valor" tabindex="-1">3.2 Propuesta de valor <a class="header-anchor" href="#_3-2-propuesta-de-valor" aria-label="Permalink to &quot;3.2 Propuesta de valor&quot;">​</a></h3><p>GoodApps Cooperativas es una <strong>plataforma en la nube</strong> que se usa desde el navegador y desde el celular, sin instalar programas, sin administrar servidores y sin realizar copias de seguridad manuales. Todas las cooperativas usan la misma plataforma, siempre actualizada, y cada una conserva sus datos completamente aislados, su marca, su vocabulario y su configuración.</p><p>La propuesta de valor se resume en seis ideas:</p><ol><li><strong>Una sola herramienta para toda la cooperativa</strong>: gestión comercial y administrativa, atención al socio, operación técnica y de campo, autogestión del socio, comunidad e integración con terceros, sobre la misma información.</li><li><strong>Todo lo que hace ProCoop, mejorado</strong>: no se pierde ninguna función del sistema actual; lo único que no se replica son sus debilidades técnicas y de seguridad (DEC-007).</li><li><strong>Configuración, no programación</strong>: servicios, tarifas, conceptos, impuestos, textos y circuitos se definen desde pantallas, con fechas de vigencia e historial de cambios.</li><li><strong>El socio en el centro</strong>: sitio y aplicación con la marca de la cooperativa para consultar, pagar, reclamar y contratar desde el celular.</li><li><strong>Control y trazabilidad</strong>: cada operación queda registrada con su autor, fecha y motivo; los documentos económicos nunca se borran, se anulan o revierten.</li><li><strong>Seguridad y continuidad profesionales</strong>: aislamiento verificable de los datos de cada cooperativa, doble factor de autenticación para el personal, cifrado, copias automáticas y niveles de servicio comprometidos.</li></ol><h3 id="_3-3-principios-del-producto" tabindex="-1">3.3 Principios del producto <a class="header-anchor" href="#_3-3-principios-del-producto" aria-label="Permalink to &quot;3.3 Principios del producto&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Principio</th><th>Qué significa para la cooperativa</th></tr></thead><tbody><tr><td>Una sola plataforma</td><td>Cada cooperativa habilita solo los servicios y módulos que contrata y necesita.</td></tr><tr><td>Configuración, no programación</td><td>Los cambios de negocio se hacen por configuración versionada, no con desarrollos a medida.</td></tr><tr><td>Vocabulario propio</td><td>La cooperativa elige cómo llamar a las cosas (socio, usuario o asociado; suministro o conexión).</td></tr><tr><td>Factura a medida</td><td>Factura separada por servicio o agrupada multiservicio, ambas modalidades completas.</td></tr><tr><td>Nada se borra</td><td>Los documentos económicos se anulan o revierten con su respaldo.</td></tr><tr><td>Inteligencia artificial que asiste</td><td>La IA propone, resume y clasifica; nunca ejecuta sin la confirmación de una persona autorizada.</td></tr><tr><td>El socio primero</td><td>Autogestión pensada para el celular, con una tarea principal clara por pantalla.</td></tr><tr><td>Seguridad desde el diseño</td><td>Datos aislados, credenciales protegidas, doble factor y mínimo privilegio.</td></tr></tbody></table><p><em>(Especificación maestra §1.3; documento de alcance funcional §3)</em></p><hr><h2 id="_4-objetivos-de-negocio-medibles" tabindex="-1">4. Objetivos de negocio medibles <a class="header-anchor" href="#_4-objetivos-de-negocio-medibles" aria-label="Permalink to &quot;4. Objetivos de negocio medibles&quot;">​</a></h2><p>Los objetivos se agrupan en compromisos de servicio (ya definidos en la especificación), objetivos de calidad de la transición (definidos en el plan de migración) y objetivos de impacto en el negocio de la cooperativa (que la especificación no cuantifica y deben acordarse con la cooperativa piloto).</p><h3 id="_4-1-compromisos-de-servicio-y-calidad-definidos-en-la-especificacion" tabindex="-1">4.1 Compromisos de servicio y calidad (definidos en la especificación) <a class="header-anchor" href="#_4-1-compromisos-de-servicio-y-calidad-definidos-en-la-especificacion" aria-label="Permalink to &quot;4.1 Compromisos de servicio y calidad (definidos en la especificación)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º</th><th>Objetivo</th><th>Meta</th><th>Fuente</th></tr></thead><tbody><tr><td>OBJ-01</td><td>Disponibilidad del servicio</td><td>99,5 % mensual (excluye mantenimientos programados)</td><td>DEC-063; T08 RNF-NFR-030</td></tr><tr><td>OBJ-02</td><td>Pérdida máxima de datos ante un incidente grave</td><td>Hasta 15 minutos</td><td>DEC-063; T08 RNF-NFR-035</td></tr><tr><td>OBJ-03</td><td>Tiempo máximo de recuperación</td><td>4 horas por cooperativa; 8 horas para la plataforma completa</td><td>DEC-063; T08 RNF-NFR-036 y 037</td></tr><tr><td>OBJ-04</td><td>Tiempo de respuesta de las pantallas</td><td>800 milisegundos o menos en el 95 % de las operaciones interactivas</td><td>DEC-063; maestra §14</td></tr><tr><td>OBJ-05</td><td>Facturación masiva</td><td>50.000 suministros en 60 minutos o menos, con progreso visible y reanudación; autorización fiscal del lote en 2 horas o menos cuando el organismo fiscal responde normalmente</td><td>T08 RNF-NFR-010 y 011 (PA-NFR-04, asumida)</td></tr><tr><td>OBJ-06</td><td>Capacidad</td><td>Cooperativas de hasta 150.000 suministros; plataforma diseñada para 100 cooperativas y ampliable a 300 sin rediseño</td><td>DEC-075</td></tr><tr><td>OBJ-07</td><td>Exactitud económica</td><td>Cero diferencias de centavos entre comprobante, cuenta corriente y contabilidad</td><td>Maestra §14</td></tr><tr><td>OBJ-08</td><td>Soporte</td><td>Lunes a viernes de 8 a 18 horas; incidentes críticos las 24 horas, todos los días</td><td>DEC-063</td></tr><tr><td>OBJ-09</td><td>Cobertura funcional respecto de ProCoop</td><td>Todas las funciones de ProCoop en alcance; la matriz de trazabilidad asigna destino al 97,9 % de las unidades de fuente relevadas, y las brechas restantes tienen corrección propuesta</td><td>DEC-007; <code>04-matriz-trazabilidad.md</code> (maestra §19)</td></tr><tr><td>OBJ-10</td><td>Seguridad y aislamiento</td><td>Pruebas automáticas de aislamiento entre cooperativas que bloquean toda actualización que no las supere; doble factor para el personal</td><td>Maestra §14; T08</td></tr></tbody></table><h3 id="_4-2-objetivos-de-calidad-de-la-transicion-definidos-en-el-plan-de-migracion" tabindex="-1">4.2 Objetivos de calidad de la transición (definidos en el plan de migración) <a class="header-anchor" href="#_4-2-objetivos-de-calidad-de-la-transicion-definidos-en-el-plan-de-migracion" aria-label="Permalink to &quot;4.2 Objetivos de calidad de la transición (definidos en el plan de migración)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>N.º</th><th>Objetivo</th><th>Meta</th><th>Fuente</th></tr></thead><tbody><tr><td>OBJ-11</td><td>Corrida paralela de facturación aprobada antes del reemplazo</td><td>2 ciclos consecutivos aprobados por servicio, con 0 diferencias sin explicar</td><td>T07 §17.4 (PRM-MIG-041 y 042; PA-MIG-02, asumida)</td></tr><tr><td>OBJ-12</td><td>Emparejamiento de facturas entre sistemas en el paralelo</td><td>99,9 % o más, con los casos no emparejados justificados</td><td>T07 §17.4</td></tr><tr><td>OBJ-13</td><td>Conciliación de saldos al corte</td><td>Deuda por titular y servicio, saldos a favor, fondos, stock y contabilidad conciliados y aprobados antes de cada corte</td><td>T07 §9.8 y §9.9</td></tr><tr><td>OBJ-14</td><td>Histórico disponible en el nuevo sistema</td><td>Ejercicio en curso más 24 meses en estructura completa; el resto en consulta histórica; copia del origen conservada 10 años</td><td>DEC-070</td></tr></tbody></table><h3 id="_4-3-objetivos-de-impacto-en-el-negocio-a-acordar-con-la-cooperativa" tabindex="-1">4.3 Objetivos de impacto en el negocio (a acordar con la cooperativa) <a class="header-anchor" href="#_4-3-objetivos-de-impacto-en-el-negocio-a-acordar-con-la-cooperativa" aria-label="Permalink to &quot;4.3 Objetivos de impacto en el negocio (a acordar con la cooperativa)&quot;">​</a></h3><p>La especificación no fija metas cuantitativas de impacto comercial u operativo. Se proponen los siguientes indicadores para que la cooperativa piloto establezca su línea de base y su meta.</p><table tabindex="0"><thead><tr><th>N.º</th><th>Indicador</th><th>Meta</th></tr></thead><tbody><tr><td>OBJ-15</td><td>Proporción de socios registrados en el portal o la aplicación</td><td>a definir</td></tr><tr><td>OBJ-16</td><td>Proporción de cobros realizados por canales digitales (pasarelas, débito, QR)</td><td>a definir</td></tr><tr><td>OBJ-17</td><td>Reducción del tiempo de resolución de reclamos y solicitudes</td><td>a definir</td></tr><tr><td>OBJ-18</td><td>Reducción de la morosidad o del plazo promedio de cobro</td><td>a definir</td></tr><tr><td>OBJ-19</td><td>Reducción del tiempo del ciclo de facturación (desde el cierre de lecturas hasta la distribución)</td><td>a definir</td></tr><tr><td>OBJ-20</td><td>Nivel de satisfacción del socio y del personal</td><td>a definir</td></tr><tr><td>OBJ-21</td><td>Costo total de operación del sistema frente al esquema actual</td><td>a definir (depende del modelo de costos, artefacto 10.3)</td></tr><tr><td>OBJ-22</td><td>Plazo total del proyecto y de cada ola</td><td>a definir (la planificación es por olas sin fechas, DEC-006)</td></tr></tbody></table><hr><h2 id="_5-alcance" tabindex="-1">5. Alcance <a class="header-anchor" href="#_5-alcance" aria-label="Permalink to &quot;5. Alcance&quot;">​</a></h2><h3 id="_5-1-soluciones-que-integra-la-plataforma" tabindex="-1">5.1 Soluciones que integra la plataforma <a class="header-anchor" href="#_5-1-soluciones-que-integra-la-plataforma" aria-label="Permalink to &quot;5.1 Soluciones que integra la plataforma&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Solución</th><th>Qué resuelve</th></tr></thead><tbody><tr><td>Gestión comercial y administrativa (ERP)</td><td>Personas y cuentas, catálogo de servicios, medición, tarifas, facturación, fiscal, cuenta corriente, cobranza, mora y financiación, ventas, compras, stock, tesorería, contabilidad, sueldos, institucional y servicios sociales.</td></tr><tr><td>Atención y relación con el socio (CRM)</td><td>Solicitudes, reclamos, mesa de entradas, turnero, canales digitales, asistente virtual e inteligencia artificial supervisada, operación técnica en campo.</td></tr><tr><td>Sitio web y autogestión</td><td>Sitio público con la marca de la cooperativa, registro, portal y aplicación del socio, pago en línea y comunidad.</td></tr><tr><td>Plataforma</td><td>Alta y ciclo de vida de cada cooperativa, licencias por módulo, ambientes de prueba, soporte controlado y monitoreo.</td></tr><tr><td>Cobranza y medios de pago</td><td>Cajas, cobradores, entes recaudadores, débitos automáticos, pasarelas de pago, códigos QR y conciliación.</td></tr><tr><td>Liquidación de impuestos</td><td>Facturación electrónica, IVA, Ingresos Brutos, percepciones, retenciones, tasas de terceros y regímenes informativos.</td></tr><tr><td>Información e integración</td><td>Reportes, tableros, inteligencia de negocio e interfaz de integración para sistemas de terceros.</td></tr></tbody></table><p><em>(Maestra §4.1; alcance funcional §4.1)</em></p><h3 id="_5-2-servicios-cubiertos" tabindex="-1">5.2 Servicios cubiertos <a class="header-anchor" href="#_5-2-servicios-cubiertos" aria-label="Permalink to &quot;5.2 Servicios cubiertos&quot;">​</a></h3><p>Cada cooperativa habilita solo los servicios que presta; cada servicio tiene su configuración, sus planes, categorías y reglas, y puede convivir con los demás en la misma cuenta del socio.</p><table tabindex="0"><thead><tr><th>Familia</th><th>Servicios</th><th>Particularidades principales</th></tr></thead><tbody><tr><td>Tecnologías de la información y las comunicaciones</td><td>Internet (fibra, inalámbrico, cable), telefonía fija e IP, televisión (cable e IPTV), correo electrónico y paquetes de mensajes</td><td>Factibilidad técnica, equipos en comodato, activación y corte automáticos en los equipos de red, tasación de llamadas, botón de baja</td></tr><tr><td>Servicios medidos</td><td>Electricidad, agua, cloacas, gas (natural por red, propano por red y envasado)</td><td>Medidores, rutas y lecturas, telemedición y prepago, tramos y escalones, generación distribuida, grandes usuarios, informes a reguladores</td></tr><tr><td>Servicios por cuenta de terceros y obras</td><td>Alumbrado público, tasas municipales y fondos, obras y contribución por mejoras</td><td>Exhibición separada en la factura, rendición al tercero, padrón de beneficiarios y planes de cuotas</td></tr><tr><td>Servicios sociales y abonos</td><td>Sepelio, cementerio parque, salud y ambulancias, banco de sangre (solo administrativo, por convenio), seguros y adhesiones</td><td>Grupo familiar, adherentes, carencias y protección reforzada de datos sensibles</td></tr><tr><td>Otros servicios</td><td>Vivienda, ventas de productos, fabricación propia (postes, bloques u otros), traslados y flota, banco ortopédico y cualquier prestación que la cooperativa defina</td><td>Contratos, cuotas, órdenes de producción</td></tr><tr><td>Institucional</td><td>Capital social y cuotas sociales</td><td>Renglón identificado en la factura, con registro propio separado de la deuda por servicios (DEC-061)</td></tr></tbody></table><p><em>(Maestra §4.2; alcance funcional §5; fichas verticales T12, DEC-073)</em></p><h3 id="_5-3-modulos-funcionales-agrupados-por-area" tabindex="-1">5.3 Módulos funcionales agrupados por área <a class="header-anchor" href="#_5-3-modulos-funcionales-agrupados-por-area" aria-label="Permalink to &quot;5.3 Módulos funcionales agrupados por área&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Área</th><th>Módulos que la componen</th></tr></thead><tbody><tr><td>Socios y servicios</td><td>Personas, titulares y cuentas; catálogo de servicios y contratos; medición y consumos</td></tr><tr><td>Facturación y fiscal</td><td>Tarifas y motor de cálculo; facturación (separada y multiservicio); fiscal e impuestos</td></tr><tr><td>Cobranza y mora</td><td>Cuenta corriente y cobranza; mora, corte, reconexión y financiación</td></tr><tr><td>Atención y operación técnica</td><td>Atención al socio (solicitudes, reclamos, mesa de entradas, turnero, canales, IA); técnica, campo y redes (factibilidad, órdenes de trabajo, cuadrillas, mapas, aprovisionamiento)</td></tr><tr><td>Gestión administrativa</td><td>Ventas y presupuestos; compras y proveedores; stock, bienes de uso y fabricación; tesorería y bancos; contabilidad</td></tr><tr><td>Personas de la organización</td><td>Personal y sueldos, con portal del empleado</td></tr><tr><td>Institucional y social</td><td>Gestión institucional (asociados, capital, asambleas, consejo, informes al organismo de control); servicios sociales y flota</td></tr><tr><td>Canales y comunidad</td><td>Sitio público y portal del socio; comunidad y comunicaciones (muro editorial, novedades, encuestas, campañas, notificaciones)</td></tr><tr><td>Transversales</td><td>Plataforma; identidad, roles y auditoría; marca, vocabulario y experiencia de uso; configuración y parámetros; integraciones; reportes, tableros e interfaz para terceros; trámites, aprobaciones y documentos; migración desde ProCoop; requisitos de calidad y seguridad</td></tr></tbody></table><h3 id="_5-4-aplicaciones" tabindex="-1">5.4 Aplicaciones <a class="header-anchor" href="#_5-4-aplicaciones" aria-label="Permalink to &quot;5.4 Aplicaciones&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aplicación</th><th>Quiénes la usan</th><th>Qué ofrece</th></tr></thead><tbody><tr><td>Sistema de gestión web (admin)</td><td>Personal administrativo, comercial, técnico y directivo</td><td>Todos los módulos de gestión, configuración, reportes y tableros, con el menú adaptado a los permisos de cada usuario</td></tr><tr><td>Portal y aplicación del socio (PWA)</td><td>Socios titulares, representantes, adherentes y visitantes registrados</td><td>Cuentas, servicios, facturas, pagos, consumos, reclamos, solicitudes, turnos, comunidad y perfil; se instala en el celular con el nombre, el ícono y los colores de la cooperativa</td></tr><tr><td>Espacio del empleado</td><td>Personal de la cooperativa</td><td>En la misma aplicación del celular: recibos de sueldo y su firma, tareas, aprobaciones y comunicaciones internas</td></tr><tr><td>Aplicación de campo (PWA)</td><td>Técnicos, lecturistas y cobradores</td><td>Agenda del día, órdenes de trabajo, rutas de lectura, cartera de cobranza, materiales en el vehículo, fotos y firma; funciona sin conexión</td></tr><tr><td>Sitio público</td><td>Público en general</td><td>Información institucional, noticias, servicios, cuadros tarifarios, registro, consulta y pago sin ingresar, solicitudes, reclamos y botón de baja</td></tr><tr><td>Tótem de autogestión</td><td>Socios en las oficinas</td><td>Turnos, consulta y pago presencial en modo kiosco</td></tr><tr><td>Consola de plataforma</td><td>Equipo operador de GoodApps</td><td>Alta y seguimiento de cooperativas, licencias, soporte y salud del servicio</td></tr><tr><td>Interfaz de integración</td><td>Sistemas de terceros autorizados</td><td>Acceso controlado a datos y operaciones (inteligencia de negocio, municipios, federaciones, otros sistemas)</td></tr></tbody></table><p><em>(Maestra §8; alcance funcional §7)</em></p><h3 id="_5-5-integraciones-externas-principales" tabindex="-1">5.5 Integraciones externas principales <a class="header-anchor" href="#_5-5-integraciones-externas-principales" aria-label="Permalink to &quot;5.5 Integraciones externas principales&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ámbito</th><th>Integraciones</th></tr></thead><tbody><tr><td>Fiscal</td><td>ARCA (autorización de comprobantes, padrones, constancias, regímenes informativos); organismos tributarios provinciales y municipales</td></tr><tr><td>Cobranza</td><td>Pagos360, Mercado Pago, SIRO y Red Link en la primera etapa (DEC-015); otras pasarelas, entes recaudadores y débitos automáticos bancarios y de tarjetas</td></tr><tr><td>Bancos</td><td>Extractos, banca electrónica empresarial, archivos de pago de haberes y proveedores, cheques electrónicos</td></tr><tr><td>Redes de Internet y televisión</td><td>MikroTik, Radius y SmartOLT para el servicio piloto (DEC-042); otras plataformas de gestión de red</td></tr><tr><td>Telefonía</td><td>Registros de llamadas de centrales y operadoras</td></tr><tr><td>Medición</td><td>Telemedición y medidores prepagos</td></tr><tr><td>Mensajería</td><td>WhatsApp Business (Meta Cloud API por defecto, DEC-055), SMS, correo electrónico y notificaciones en el celular</td></tr><tr><td>Identidad</td><td>Ingreso con cuentas de Google y corporativas; Ciudadano Digital de Córdoba habilitable por cooperativa (DEC-067)</td></tr><tr><td>Mapas</td><td>Servicio oficial de georreferenciación para normalizar domicilios y mapas con autocompletado de direcciones (DEC-046)</td></tr><tr><td>Inteligencia artificial y firma</td><td>Proveedores de IA para atención, moderación y lectura de documentos; proveedor licenciado de firma digital para recibos de sueldo y actas (DEC-078)</td></tr><tr><td>Reguladores y control</td><td>Entes de energía, gas y comunicaciones; organismo de control cooperativo; federaciones</td></tr><tr><td>Equipamiento local</td><td>Impresoras fiscales y de tickets, lectores, balanzas, pantallas y tótems, mediante un agente local</td></tr></tbody></table><h3 id="_5-6-diagrama-de-contexto-de-negocio" tabindex="-1">5.6 Diagrama de contexto de negocio <a class="header-anchor" href="#_5-6-diagrama-de-contexto-de-negocio" aria-label="Permalink to &quot;5.6 Diagrama de contexto de negocio&quot;">​</a></h3><p>El siguiente diagrama muestra, de manera simplificada, quiénes interactúan con GoodApps Cooperativas y con qué entes externos se intercambia información.</p>',61)),(o(),r(n,null,{default:e(()=>[d(t,{id:"mermaid-1355",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20ACT%5B%22Actores%20de%20la%20cooperativa%22%5D%0A%20%20%20%20%20%20%20%20SOC%5B%22Socios%2C%20representantes%20y%20adherentes%22%5D%0A%20%20%20%20%20%20%20%20PER%5B%22Personal%20administrativo%20y%20de%20atenci%C3%B3n%22%5D%0A%20%20%20%20%20%20%20%20CAM%5B%22Personal%20de%20campo%3A%20t%C3%A9cnicos%2C%20lecturistas%20y%20cobradores%22%5D%0A%20%20%20%20%20%20%20%20DIR%5B%22Consejo%2C%20gerencia%20y%20sindicatura%22%5D%0A%20%20%20%20%20%20%20%20PUB%5B%22P%C3%BAblico%20en%20general%22%5D%0A%20%20%20%20%20%20%20%20PRV%5B%22Proveedores%20invitados%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20GA((%22GoodApps%20Cooperativas%22))%0A%0A%20%20%20%20subgraph%20EXT%5B%22Entes%20y%20servicios%20externos%22%5D%0A%20%20%20%20%20%20%20%20FIS%5B%22ARCA%20y%20organismos%20tributarios%22%5D%0A%20%20%20%20%20%20%20%20COB%5B%22Pasarelas%20de%20pago%2C%20entes%20recaudadores%20y%20bancos%22%5D%0A%20%20%20%20%20%20%20%20RED%5B%22Equipos%20de%20red%2C%20telefon%C3%ADa%20y%20telemedici%C3%B3n%22%5D%0A%20%20%20%20%20%20%20%20MSG%5B%22Mensajer%C3%ADa%3A%20WhatsApp%2C%20SMS%20y%20correo%22%5D%0A%20%20%20%20%20%20%20%20REG%5B%22Reguladores%20y%20organismo%20de%20control%20cooperativo%22%5D%0A%20%20%20%20%20%20%20%20IDM%5B%22Identidad%20digital%20y%20mapas%22%5D%0A%20%20%20%20%20%20%20%20IA%5B%22Inteligencia%20artificial%20y%20firma%20digital%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20PLA%5B%22Equipo%20operador%20de%20la%20plataforma%22%5D%0A%20%20%20%20LEG%5B%22Sistema%20heredado%20ProCoop%20durante%20la%20convivencia%22%5D%0A%0A%20%20%20%20SOC%20%3C--%3E%20GA%0A%20%20%20%20PER%20%3C--%3E%20GA%0A%20%20%20%20CAM%20%3C--%3E%20GA%0A%20%20%20%20DIR%20%3C--%3E%20GA%0A%20%20%20%20PUB%20--%3E%20GA%0A%20%20%20%20PRV%20%3C--%3E%20GA%0A%20%20%20%20PLA%20%3C--%3E%20GA%0A%20%20%20%20GA%20%3C--%3E%20FIS%0A%20%20%20%20GA%20%3C--%3E%20COB%0A%20%20%20%20GA%20%3C--%3E%20RED%0A%20%20%20%20GA%20--%3E%20MSG%0A%20%20%20%20GA%20--%3E%20REG%0A%20%20%20%20GA%20%3C--%3E%20IDM%0A%20%20%20%20GA%20%3C--%3E%20IA%0A%20%20%20%20LEG%20-.-%3E%20GA%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<hr><h2 id="_6-fuera-de-alcance" tabindex="-1">6. Fuera de alcance <a class="header-anchor" href="#_6-fuera-de-alcance" aria-label="Permalink to &quot;6. Fuera de alcance&quot;">​</a></h2><p>La especificación <strong>no establece exclusiones funcionales</strong>: todo lo que hace ProCoop está en alcance, mejorado, y las funciones de menor prioridad se ubican en olas tardías, pero no se excluyen (DEC-007; maestra §4.4).</p><p>Lo que <strong>no se replica</strong> del sistema actual son sus deudas técnicas y de seguridad, que se reemplazan por la solución indicada en la especificación:</p><table tabindex="0"><thead><tr><th>No se replica</th><th>Se reemplaza por</th></tr></thead><tbody><tr><td>Contraseñas que pueden descifrarse</td><td>Contraseñas protegidas con algoritmos no reversibles y doble factor para el personal</td></tr><tr><td>Usuario de base de datos compartido</td><td>Identidad individual por usuario, con permisos y auditoría</td></tr><tr><td>Claves y credenciales escritas dentro del programa</td><td>Bóveda cifrada de credenciales por cooperativa (DEC-074)</td></tr><tr><td>Una base de datos por cooperativa</td><td>Plataforma única con datos aislados por cooperativa (DEC-002)</td></tr><tr><td>Portal del socio con copia sincronizada en otra base</td><td>Portal nativo sobre la misma información (M19)</td></tr><tr><td>Instalación local y actualizaciones manuales</td><td>Servicio en la nube con actualizaciones automáticas</td></tr><tr><td>Menú armado automáticamente a partir del código del programa</td><td>Menú, mapa del sitio y permisos generados desde una única declaración verificable</td></tr><tr><td>Parámetros numéricos sin significado</td><td>Parámetros con nombre, tipo, vigencia e historial</td></tr></tbody></table><p>Además, la especificación fija <strong>límites de responsabilidad</strong> que conviene tener presentes (alcance funcional §6.1):</p><ul><li>La presentación de declaraciones fiscales y la responsabilidad fiscal siguen siendo de la cooperativa y de su profesional contable; el sistema calcula, prepara, valida y concilia.</li><li>El sistema no certifica la validez legal de los actos institucionales ni reemplaza a los órganos sociales.</li><li>En salud y servicios sociales se gestionan solo aspectos administrativos: no hay historias clínicas, decisiones clínicas ni despacho de emergencias.</li><li>La inteligencia artificial nunca ejecuta acciones con efecto sin confirmación humana y permanece apagada hasta que la cooperativa la acepta (DEC-056).</li><li>Los plazos y criterios con contenido jurídico vienen precargados con valores de referencia y deben ser validados por la asesoría legal de la cooperativa antes de su primera aplicación productiva.</li></ul><hr><h2 id="_7-usuarios-y-actores" tabindex="-1">7. Usuarios y actores <a class="header-anchor" href="#_7-usuarios-y-actores" aria-label="Permalink to &quot;7. Usuarios y actores&quot;">​</a></h2><p>La plataforma reconoce cuatro grandes grupos de usuarios, con un catálogo de <strong>40 roles</strong> predefinidos que cada cooperativa puede usar tal cual, copiar y ajustar; los nombres visibles se adaptan al vocabulario de la cooperativa (maestra §7.2; T02).</p><table tabindex="0"><thead><tr><th>Grupo</th><th>Actores principales</th><th>Interacción con el sistema</th></tr></thead><tbody><tr><td>Conducción de la cooperativa</td><td>Consejeros, gerente, síndico o auditor</td><td>Tableros, aprobaciones de alto nivel, lectura institucional y auditoría sin modificar información</td></tr><tr><td>Personal administrativo</td><td>Facturación, cajeros, tesorería, contaduría, compras, depósito, recursos humanos, secretaría institucional, servicios sociales</td><td>Sistema de gestión web, cada uno con su alcance de datos (sucursal, zona, servicio, depósito)</td></tr><tr><td>Personal comercial y de atención</td><td>Atención al socio, supervisión de atención, editores y moderadores de comunidad</td><td>Sistema de gestión web, canales digitales y muro editorial</td></tr><tr><td>Personal técnico y de campo</td><td>Supervisor técnico, supervisor de consumos, técnicos, lecturistas, cobradores</td><td>Sistema de gestión web y aplicación de campo sin conexión</td></tr><tr><td>Administración del sistema en la cooperativa</td><td>Administrador de la cooperativa y administrador de usuarios</td><td>Configuración, usuarios, roles, políticas y publicación</td></tr><tr><td>Comunidad</td><td>Socios titulares, representantes autorizados, adherentes, visitantes registrados, empleados en el portal, proveedores invitados</td><td>Portal y aplicación del socio, sitio público, tótem</td></tr><tr><td>Equipo de la plataforma</td><td>Superadministración, operación de cooperativas, comercial, soporte, seguridad, operaciones técnicas</td><td>Consola de plataforma; acceso a datos de una cooperativa solo temporal, consentido y auditado</td></tr><tr><td>Dispositivos y sistemas</td><td>Procesos automáticos, sistemas externos integrados, asistente virtual, tótems y agentes de equipamiento local</td><td>Permisos propios y acotados; el asistente nunca tiene más permisos que el usuario en cuyo nombre actúa</td></tr></tbody></table><p>Lo que cada usuario puede ver y hacer resulta de cuatro filtros verificados en cada operación: <strong>licencia</strong> contratada, <strong>activación</strong> del módulo por la cooperativa, <strong>rol</strong> del usuario y <strong>alcance de datos</strong>. Se suman la denegación por defecto, la separación de funciones (quien solicita no aprueba, quien aprueba no paga), la autorización de supervisor y la franja horaria por perfil.</p><hr><h2 id="_8-beneficios-esperados-por-actor" tabindex="-1">8. Beneficios esperados por actor <a class="header-anchor" href="#_8-beneficios-esperados-por-actor" aria-label="Permalink to &quot;8. Beneficios esperados por actor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actor</th><th>Beneficios esperados</th></tr></thead><tbody><tr><td>Consejo de administración y sindicatura</td><td>Información confiable y trazable para decidir; auditoría inmutable de todas las operaciones; separación de funciones y circuitos de aprobación; cumplimiento normativo con evidencia; menor riesgo de seguridad sobre los datos de los socios.</td></tr><tr><td>Gerencia</td><td>Tableros por rol con indicadores definidos; visión integrada de todos los servicios en un solo sistema; capacidad de adaptar tarifas, conceptos y políticas por configuración; niveles de servicio comprometidos por el proveedor.</td></tr><tr><td>Facturación, fiscal y contaduría</td><td>Facturación masiva con controles previos, simulación y comparación con el período anterior; autorización fiscal electrónica con contingencias; cero diferencias entre factura, cuenta corriente y contabilidad; asientos automáticos desde el primer evento económico (DEC-009).</td></tr><tr><td>Cobranza y tesorería</td><td>Cobro por todos los canales con imputación automática; conciliación de pasarelas, entes y bancos; reconexión automática al pagar en servicios remotos (DEC-014); reconocimiento de los códigos de pago de facturas emitidas por ProCoop hasta su vencimiento (DEC-050).</td></tr><tr><td>Atención al socio</td><td>Expediente único con número de seguimiento, plazos de respuesta y avisos automáticos; canales digitales y WhatsApp integrados; asistencia de IA para clasificar y resumir, siempre bajo control humano.</td></tr><tr><td>Personal técnico y de campo</td><td>Agenda y órdenes en el celular, aun sin conexión; fotos, firma del socio y materiales del vehículo registrados en el momento; activación automática del servicio en los equipos de red.</td></tr><tr><td>Administración y recursos humanos</td><td>Compras, stock, tesorería, contabilidad y sueldos integrados con el resto de la operación; recibos de sueldo digitales con firma.</td></tr><tr><td>Socios y comunidad</td><td>Autogestión desde el celular con la marca de su cooperativa: consultar, pagar, reclamar, contratar y seguir sus gestiones; avisos por el canal preferido; comunidad con novedades y encuestas; información siempre actualizada.</td></tr><tr><td>Equipo de sistemas de la cooperativa</td><td>Sin servidores ni copias de seguridad propias que administrar; actualizaciones automáticas; ambiente de prueba con datos anonimizados para validar cambios.</td></tr></tbody></table><hr><h2 id="_9-enfoque-de-implementacion" tabindex="-1">9. Enfoque de implementación <a class="header-anchor" href="#_9-enfoque-de-implementacion" aria-label="Permalink to &quot;9. Enfoque de implementación&quot;">​</a></h2><h3 id="_9-1-construccion-por-olas" tabindex="-1">9.1 Construcción por olas <a class="header-anchor" href="#_9-1-construccion-por-olas" aria-label="Permalink to &quot;9.1 Construcción por olas&quot;">​</a></h3><p>El sistema se construye en <strong>doce olas sucesivas (O0 a O11)</strong>. Cada ola entrega funciones completas y utilizables, y tiene un hito de salida verificable. Por decisión del solicitante, las olas <strong>no tienen fechas</strong> comprometidas: solo orden y dependencias (DEC-006). El plan detallado contiene 172 instrucciones de construcción que cubren los 4.203 requisitos funcionales y los 292 requisitos no funcionales de la especificación (<code>03-plan-de-olas-y-prompts.md</code>).</p><p>El primer recorrido completo de punta a punta es el del <strong>servicio de Internet</strong> (DEC-005): contratación, factibilidad, instalación, equipo en comodato, activación, facturación, pago, reclamo, mora y baja. Las olas O2 a O6 lo completan; los servicios medidos llegan en O7 y la gestión administrativa e institucional completa en las olas siguientes.</p><table tabindex="0"><thead><tr><th>Ola</th><th>Qué entrega, en términos de negocio</th><th>Hito de salida</th></tr></thead><tbody><tr><td>O0</td><td>Fundaciones: seguridad, ingreso, aislamiento entre cooperativas, auditoría, marca y vocabulario básicos; entidades jurídicas y sucursales de la cooperativa</td><td>Una cooperativa de demostración con ingreso seguro y aislamiento verificado</td></tr><tr><td>O1</td><td>Plataforma y configuración: usuarios, roles, permisos, parámetros, tablas maestras, geografía, circuitos de aprobación y repositorio documental</td><td>Alta asistida de una cooperativa con su configuración publicada</td></tr><tr><td>O2</td><td>Socios, servicios y portal: personas y cuentas, catálogo de servicios, sitio público, registro, portal, solicitudes y comunidad</td><td>Un socio se registra y solicita Internet desde el sitio</td></tr><tr><td>O3</td><td>Técnica de Internet: factibilidad, agenda, órdenes de trabajo, instalación, comodato, stock de equipos, aplicación de campo y activación en la red</td><td>El servicio queda instalado y activo</td></tr><tr><td>O4</td><td>Tarifas, facturación y fiscal: motor tarifario, facturación, autorización fiscal electrónica, impuestos básicos y adherentes</td><td>Primera factura electrónica autorizada</td></tr><tr><td>O5</td><td>Cobranza y tesorería operativa: cuenta corriente, caja, pasarelas prioritarias, débitos, conciliación, contabilidad inicial y capital social mínimo</td><td>Pago en línea imputado y registrado contablemente</td></tr><tr><td>O6</td><td>Mora y atención avanzada: suspensión, corte y reconexión, convenios, incobrables, inteligencia artificial y atención omnicanal</td><td>Recorrido de Internet completo de punta a punta</td></tr><tr><td>O7</td><td>Servicios medidos: electricidad, agua, cloacas, gas y alumbrado; lecturas, telemedición, tarifas medidas, reguladores y obras; corrida paralela y corte comercial por servicio (DEC-089)</td><td>Facturación de energía con lecturas; corte comercial de electricidad, gas y prepago de Laguna Larga al cerrar la ola (DEC-089)</td></tr><tr><td>O8</td><td>Gestión administrativa: compras, stock completo, tesorería, contabilidad completa, regímenes informativos; importación de sueldos de un liquidador externo</td><td>Cierre contable mensual</td></tr><tr><td>O9</td><td>Personal y sueldos: liquidación propia con sus obligaciones</td><td>Liquidación mensual con sus declaraciones</td></tr><tr><td>O10</td><td>Institucional y servicios sociales: asociados, asambleas, sepelio, cementerio, salud, vivienda, flota, telefonía, televisión, fabricación, turnero y actividades</td><td>Asamblea y servicios sociales operativos</td></tr><tr><td>O11</td><td>Información, integración y reemplazo: inteligencia de negocio, generador de reportes, interfaz para terceros, pasarelas restantes, migración repetible y reemplazo del área administrativa (DEC-089; antes incluía la corrida paralela, que pasa a O7)</td><td>Reemplazo del área administrativa y apagado de ProCoop (DEC-089; antes &quot;por etapas en una cooperativa: primero el área comercial y luego la administrativa&quot;)</td></tr></tbody></table><p><em>(Maestra §15; alcance funcional §14)</em></p><h3 id="_9-2-hoja-de-ruta-ilustrativa" tabindex="-1">9.2 Hoja de ruta ilustrativa <a class="header-anchor" href="#_9-2-hoja-de-ruta-ilustrativa" aria-label="Permalink to &quot;9.2 Hoja de ruta ilustrativa&quot;">​</a></h3><p>El siguiente diagrama es <strong>ilustrativo</strong>: muestra la secuencia relativa de las olas, sin fechas ni duraciones reales.</p>',24)),(o(),r(n,null,{default:e(()=>[d(t,{id:"mermaid-1850",class:"mermaid",graph:"timeline%0A%20%20%20%20title%20Hoja%20de%20ruta%20ilustrativa%20por%20olas%2C%20secuencia%20relativa%20sin%20fechas%0A%20%20%20%20section%20Bases%0A%20%20%20%20%20%20%20%20O0%20Fundaciones%20%3A%20Seguridad%2C%20ingreso%20y%20aislamiento%20entre%20cooperativas%0A%20%20%20%20%20%20%20%20O1%20Plataforma%20y%20configuraci%C3%B3n%20%3A%20Usuarios%2C%20roles%2C%20par%C3%A1metros%20y%20aprobaciones%0A%20%20%20%20section%20Piloto%20Internet%20de%20punta%20a%20punta%0A%20%20%20%20%20%20%20%20O2%20Socios%20y%20portal%20%3A%20Registro%20del%20socio%20y%20solicitud%20de%20Internet%0A%20%20%20%20%20%20%20%20O3%20T%C3%A9cnica%20de%20Internet%20%3A%20Instalaci%C3%B3n%20y%20activaci%C3%B3n%20del%20servicio%0A%20%20%20%20%20%20%20%20O4%20Facturaci%C3%B3n%20y%20fiscal%20%3A%20Primera%20factura%20electr%C3%B3nica%20autorizada%0A%20%20%20%20%20%20%20%20O5%20Cobranza%20y%20tesorer%C3%ADa%20%3A%20Pago%20en%20l%C3%ADnea%20imputado%20y%20registrado%0A%20%20%20%20%20%20%20%20O6%20Mora%20y%20atenci%C3%B3n%20avanzada%20%3A%20Recorrido%20de%20Internet%20completo%0A%20%20%20%20section%20Ampliaci%C3%B3n%20de%20servicios%20y%20gesti%C3%B3n%0A%20%20%20%20%20%20%20%20O7%20Servicios%20medidos%20%3A%20Energ%C3%ADa%2C%20agua%2C%20cloacas%20y%20gas%20con%20lecturas%0A%20%20%20%20%20%20%20%20O8%20Gesti%C3%B3n%20administrativa%20%3A%20Cierre%20contable%20mensual%0A%20%20%20%20%20%20%20%20O9%20Sueldos%20%3A%20Liquidaci%C3%B3n%20mensual%20propia%0A%20%20%20%20%20%20%20%20O10%20Institucional%20y%20social%20%3A%20Asambleas%20y%20servicios%20sociales%0A%20%20%20%20section%20Reemplazo%20de%20ProCoop%0A%20%20%20%20%20%20%20%20O11%20Integracion%20y%20reemplazo%20%3A%20Corte%20administrativo%20y%20apagado%20de%20ProCoop%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<h3 id="_9-3-cooperativa-piloto" tabindex="-1">9.3 Cooperativa piloto <a class="header-anchor" href="#_9-3-cooperativa-piloto" aria-label="Permalink to &quot;9.3 Cooperativa piloto&quot;">​</a></h3><p>La cooperativa piloto (comercial y de migración) es <strong>Laguna Larga</strong> (sigla <code>LAG</code>) (DEC-088, que reemplaza a DEC-081). Su base de ProCoop es además la base relevada de referencia para el mapeo de datos, las pruebas de corrida paralela y las verificaciones de reglas heredadas; de ella se toma solo configuración, nunca datos personales.</p><p>Laguna Larga opera servicios medidos (electricidad, gas y prepago; T07 CTR-MIG-07). Por eso, según la opción asumida para el orden de migración (PA-MIG-17, DEC-072), la herramienta de migración se valida primero con datos sintéticos de Internet y la <strong>primera migración real de Laguna Larga se realiza después de la ola O7</strong>, cuando los servicios medidos están completos. El corte avanza luego por etapas y por dominio hasta la ola O11 (DEC-068). Las cooperativas siguientes reutilizan el mismo conjunto de mapeo y solo agregan sus particularidades.</p><h3 id="_9-4-migracion-desde-procoop" tabindex="-1">9.4 Migración desde ProCoop <a class="header-anchor" href="#_9-4-migracion-desde-procoop" aria-label="Permalink to &quot;9.4 Migración desde ProCoop&quot;">​</a></h3><p>La migración se trata como un proyecto por cooperativa, organizado por dominio funcional, con trazabilidad completa (T07):</p><ul><li><strong>Herramienta desde el inicio</strong>: la herramienta de migración se construye en las olas O0 y O1, y cada módulo incorpora su cargador de datos en la ola en que se construye, probado con datos anonimizados.</li><li><strong>Fases controladas</strong>: inventario, diagnóstico de calidad de datos, mapeo, limpieza, extracción, transformación, carga, validación, conciliación, corrida paralela, convivencia, corte definitivo y, si hiciera falta, vuelta atrás. Cada fase tiene una salida verificable y un responsable.</li><li><strong>Calidad de datos</strong>: se detectan documentos inválidos, personas duplicadas, domicilios sin normalizar y registros huérfanos; los casos se resuelven en una cola de saneamiento con aprobación humana.</li><li><strong>Histórico</strong>: ejercicio en curso más 24 meses en estructura completa; el resto queda disponible para consulta histórica, y la copia del origen se conserva 10 años (DEC-070).</li><li><strong>Corrida paralela</strong>: antes de reemplazar la facturación se compara factura por factura lo que emite ProCoop con lo que simula GoodApps, en cantidades, importes por concepto, impuestos y vencimientos, hasta aprobar 2 ciclos consecutivos por servicio sin diferencias sin explicar.</li><li><strong>Continuidad para el socio</strong>: los códigos de pago de las facturas emitidas por ProCoop se siguen reconociendo hasta su vencimiento (DEC-050) y los usuarios del portal anterior se incorporan sin nuevo registro.</li><li><strong>Vuelta atrás</strong>: existe un plan de retorno a ProCoop que puede aplicarse hasta la primera emisión fiscal real o el primer cobro por entes en GoodApps; después, solo se corrige hacia adelante. Toda decisión de vuelta atrás requiere doble aprobación.</li></ul><h3 id="_9-5-corte-por-etapas-dec-068" tabindex="-1">9.5 Corte por etapas (DEC-068) <a class="header-anchor" href="#_9-5-corte-por-etapas-dec-068" aria-label="Permalink to &quot;9.5 Corte por etapas (DEC-068)&quot;">​</a></h3><p>El reemplazo de ProCoop se hace <strong>por etapas</strong>, con un único sistema responsable de cada dominio en cada momento:</p><table tabindex="0"><thead><tr><th>Etapa</th><th>GoodApps es el sistema de registro de</th><th>ProCoop sigue siendo el sistema de registro de</th></tr></thead><tbody><tr><td>Ensayos</td><td>Ninguno (pruebas en un ambiente de ensayo)</td><td>Todo</td></tr><tr><td>Paralelo comercial</td><td>Ninguno (GoodApps simula y compara)</td><td>Todo</td></tr><tr><td>Corte comercial</td><td>Personas, cuentas, contratos, catálogo, tarifas, medición, facturación, fiscal de ventas, cuenta corriente, cobranza, mora, financiación, atención, técnica, portal y comunicaciones</td><td>Compras, stock no serializado, tesorería, contabilidad oficial, sueldos, institucional y social</td></tr><tr><td>Corte administrativo</td><td>Además: compras, stock, tesorería, contabilidad y retenciones</td><td>Sueldos, institucional y social, si todavía no fueron cortados</td></tr><tr><td>Apagado</td><td>Todo</td><td>Solo consulta hasta el cierre del ejercicio; luego, archivo</td></tr></tbody></table><p>Durante la convivencia, la contabilidad oficial sigue en ProCoop; GoodApps registra en un plan contable marcado como no oficial, lo concilia contra ProCoop y se oficializa en el corte administrativo (DEC-069). Una vez cortado un dominio, ProCoop queda en solo lectura para ese dominio.</p><hr><h2 id="_10-principales-decisiones-tomadas" tabindex="-1">10. Principales decisiones tomadas <a class="header-anchor" href="#_10-principales-decisiones-tomadas" aria-label="Permalink to &quot;10. Principales decisiones tomadas&quot;">​</a></h2><p>La especificación registra 87 decisiones del solicitante (DEC-001 a DEC-087). De las 516 preguntas del cuestionario, 93 fueron respondidas por el solicitante y 423 se asumieron con la opción recomendada, que puede revisarse en cualquier momento (DEC-047, DEC-072). Las más relevantes para la conducción de la cooperativa son las siguientes.</p><p><strong>Producto y alcance</strong></p><ul><li>Todo lo que hace ProCoop está en alcance, incluidas telefonía, televisión, vivienda, salud, sepelio, fabricación, flota y turnero; las funciones menos prioritarias van a olas tardías (DEC-007).</li><li>El servicio piloto es Internet, que se completa de punta a punta antes de incorporar los servicios medidos (DEC-005).</li><li>La planificación es por olas sin fechas; solo hay orden y dependencias (DEC-006).</li><li>Cada servicio queda especificado de punta a punta en una ficha vertical, que sirve como control de cobertura (DEC-073).</li></ul><p><strong>Plataforma, seguridad y datos</strong></p><ul><li>Una única plataforma compartida, con los datos de cada cooperativa aislados por un identificador propio y verificados con pruebas automáticas (DEC-002).</li><li>Alojamiento en la nube en la región de San Pablo, con cláusulas contractuales de transferencia internacional conformes a la autoridad argentina de protección de datos, y diseño independiente del proveedor de nube (DEC-004, DEC-062).</li><li>Niveles de servicio: 99,5 % de disponibilidad mensual, pérdida máxima de datos de 15 minutos, recuperación en 4 horas por cooperativa y soporte en días hábiles con atención de incidentes críticos las 24 horas (DEC-063).</li><li>GoodApps actúa como prestador de servicios de tratamiento de datos por cuenta de la cooperativa, con contrato de encargo (DEC-076).</li><li>Las credenciales de ARCA, bancos y pasarelas se guardan en una bóveda cifrada; nunca se transcriben ni se registran (DEC-074).</li><li>Una cooperativa puede administrar varias personas jurídicas, con emisión, contabilidad y sueldos por entidad (DEC-064).</li></ul><p><strong>Facturación, cobranza y mora</strong></p><ul><li>La factura es separada por servicio por defecto; la factura agrupada multiservicio se habilita por grupo (DEC-034).</li><li>Ante caídas del organismo fiscal, se emite y se encola la autorización, con contingencia cuando está habilitada (DEC-018, DEC-038).</li><li>Pagos360, Mercado Pago, SIRO y Red Link se integran en la primera etapa de cobranza; el resto más adelante (DEC-015).</li><li>Los pagos se imputan por antigüedad, primero recargos e intereses, respetando la elección explícita del socio o del cajero (DEC-048).</li><li>La reconexión es automática al confirmarse el pago en servicios remotos; si requiere técnico, se genera la orden de trabajo (DEC-014).</li><li>La deuda queda en el titular que la generó; el cambio de titularidad no la traslada salvo convenio (DEC-045). La deuda previa en un domicilio genera advertencia, nunca bloqueo (DEC-029).</li><li>Los plazos de prescripción se diferencian por tipo de obligación (24 meses para facturas periódicas de servicios y 60 meses para el resto) y requieren validación legal antes de su primera aplicación (DEC-052).</li></ul><p><strong>Atención, comunidad y socio</strong></p><ul><li>La comunidad es un muro editorial: publica la cooperativa; los socios reaccionan y comentan con moderación (DEC-008).</li><li>La inteligencia artificial en atención clasifica, resume y sugiere, y permanece apagada hasta que la cooperativa la acepta (DEC-056).</li><li>El socio ingresa con contraseña o con un código de un solo uso, según lo que habilite la cooperativa (DEC-066).</li><li>Firma electrónica con código de un solo uso por defecto; firma digital con proveedor licenciado para recibos de sueldo y actas (DEC-078).</li></ul><p><strong>Gestión administrativa y transición</strong></p><ul><li>La contabilidad tiene un núcleo temprano (ola O5) y se completa en la ola O8 (DEC-009).</li><li>Sueldos: primero importación desde un liquidador externo (O8) y luego liquidación propia con dos períodos en paralelo (O9) (DEC-058).</li><li>El reemplazo de ProCoop es por etapas: primero el área comercial y luego la administrativa (DEC-068), con contabilidad oficial en ProCoop durante la convivencia (DEC-069).</li><li>Histórico migrado: ejercicio en curso más 24 meses, con copia del origen por 10 años (DEC-070).</li><li>Modelo comercial: paquetes por tamaño con complementos y cupos según contratos activos (DEC-065).</li><li>La cooperativa piloto es Laguna Larga (DEC-088) y facilitará la información y los accesos que requiera el proyecto.</li></ul><hr><h2 id="_11-riesgos-principales-y-mitigacion" tabindex="-1">11. Riesgos principales y mitigación <a class="header-anchor" href="#_11-riesgos-principales-y-mitigacion" aria-label="Permalink to &quot;11. Riesgos principales y mitigación&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N.º</th><th>Riesgo</th><th>Impacto</th><th>Mitigación</th></tr></thead><tbody><tr><td>R-01</td><td><strong>Migración de datos</strong>: calidad deficiente de los datos heredados (documentos inválidos, duplicados, domicilios sin normalizar, registros huérfanos) o diferencias en saldos y facturación</td><td>Alto: errores en facturas y deudas, pérdida de confianza del socio, demoras en el corte</td><td>Herramienta de migración desde O0–O1; diagnóstico de calidad y cola de saneamiento con aprobación humana; conciliaciones por dominio; corrida paralela con 2 ciclos aprobados y 0 diferencias sin explicar; plan de vuelta atrás con doble aprobación (T07)</td></tr><tr><td>R-02</td><td><strong>Validaciones legales pendientes</strong>: 8 parámetros con valor por defecto propuesto que requieren validación legal (tratamiento fiscal del aporte de capital en la factura; tiempos de respuesta ante emergencias de gas; suspensión de cobertura de sepelio por cuotas impagas y carencia de rehabilitación; modo de mora en telefonía con emergencias siempre habilitadas; grilla mínima de televisión en mora; plazos de respuesta de reclamos de servicios TIC; caudal mínimo vital de agua; ventanas de corte de energía por jurisdicción), además de los plazos de prescripción (DEC-052) y los de conservación de datos (PA-NFR-06)</td><td>Alto: incumplimientos normativos, reclamos o sanciones si se aplican valores no validados</td><td>Los valores vienen como parámetros editables y marcados para validación; la especificación exige validación legal antes de la primera aplicación productiva; ningún administrador puede desactivar restricciones normativas (<code>05-registro-huecos.md</code>; alcance funcional §6.1)</td></tr><tr><td>R-03</td><td><strong>Datos heredados marcados [VERIFICAR]</strong>: reglas y valores tomados de ProCoop y de la base relevada de referencia que deben confirmarse con la cooperativa piloto</td><td>Medio: comportamientos distintos de los esperados en la cooperativa real</td><td>Verificación en las fases de inventario y mapeo de la cooperativa piloto; corrida paralela factura por factura; diferencias intencionales documentadas como regla</td></tr><tr><td>R-04</td><td><strong>Dependencia de servicios externos</strong>: indisponibilidad o cambios del organismo fiscal, pasarelas, bancos, entes recaudadores, mensajería, mapas o equipos de red</td><td>Alto: demoras en autorización fiscal, cobros o activaciones</td><td>Conectores con reintentos controlados y prevención de duplicados; operación degradada sin bloquear pantallas; contingencias fiscales; tablero de conectores degradados; credenciales en bóveda con aviso de vencimiento (T06; T08 RNF-NFR-047)</td></tr><tr><td>R-05</td><td><strong>Adopción de usuarios</strong>: resistencia al cambio del personal, curva de aprendizaje y baja adopción digital de los socios</td><td>Alto: subutilización del sistema y menor retorno de la inversión</td><td>Ayuda contextual en cada pantalla; vocabulario propio de la cooperativa; ambiente de prueba; incorporación de usuarios del portal anterior sin nuevo registro; plan de capacitación y gestión del cambio (artefacto 8.4, pendiente)</td></tr><tr><td>R-06</td><td><strong>Alcance amplio</strong>: más de 4.200 requisitos funcionales en 12 olas, con riesgo de demoras o de pérdida de foco</td><td>Alto: retrasos en el reemplazo y en los beneficios</td><td>Construcción por olas con hitos de salida verificables; piloto Internet de punta a punta primero; prioridades que ubican lo marginal en olas tardías; trazabilidad de cada requisito a una instrucción de construcción</td></tr><tr><td>R-07</td><td><strong>Piloto con servicios medidos</strong>: Laguna Larga opera electricidad, gas y prepago, mientras que el primer servicio construido de punta a punta es Internet (DEC-005)</td><td>Medio: la primera migración real no puede hacerse antes de completar la ola O7</td><td>Validar la herramienta con datos sintéticos de Internet; ensayos de migración con la base de Laguna Larga desde las olas tempranas; primera migración real después de O7 (PA-MIG-17)</td></tr><tr><td>R-08</td><td><strong>Decisiones asumidas</strong> (423 preguntas con opción recomendada) que la cooperativa podría querer cambiar</td><td>Medio: retrabajo si una decisión cambia tarde</td><td>Las opciones asumidas se implementan detrás de parámetros cambiables; revisión priorizada de las de mayor impacto antes de la ola correspondiente</td></tr><tr><td>R-09</td><td><strong>Convivencia de dos sistemas</strong> durante el corte por etapas</td><td>Medio: doble carga, inconsistencias entre sistemas</td><td>Un único sistema de registro por dominio; ProCoop en solo lectura para lo cortado; sincronizaciones definidas; contabilidad no oficial conciliada (DEC-068, DEC-069)</td></tr><tr><td>R-10</td><td><strong>Privacidad y alojamiento fuera del país</strong></td><td>Medio: observaciones de la autoridad de protección de datos o de los socios</td><td>Cláusulas contractuales de transferencia (DEC-062); rol de prestador de servicios de tratamiento con contrato de encargo (DEC-076); consentimientos, derechos y retención gestionados (T08)</td></tr><tr><td>R-11</td><td><strong>Metas de rendimiento asumidas</strong> sin medición real (facturación masiva y procesos por lotes)</td><td>Medio: tiempos de proceso superiores a los esperados en cooperativas grandes</td><td>Pruebas de carga con datos de referencia antes de cerrar las olas clave; recalibración con las mediciones de la cooperativa piloto (T08 §7.1)</td></tr></tbody></table><hr><h2 id="_12-supuestos-y-dependencias" tabindex="-1">12. Supuestos y dependencias <a class="header-anchor" href="#_12-supuestos-y-dependencias" aria-label="Permalink to &quot;12. Supuestos y dependencias&quot;">​</a></h2><h3 id="_12-1-supuestos" tabindex="-1">12.1 Supuestos <a class="header-anchor" href="#_12-1-supuestos" aria-label="Permalink to &quot;12.1 Supuestos&quot;">​</a></h3><ol><li>Las preguntas no consultadas rigen con su opción recomendada hasta que la cooperativa las revise (DEC-047, DEC-072).</li><li>El perfil de capacidad de referencia (cooperativa estándar de 25.000 suministros y grande de 150.000) es representativo y se recalibrará con las mediciones de la cooperativa piloto (DEC-075; T08 §7.1).</li><li>La cooperativa piloto facilitará acceso de solo lectura a su base de ProCoop y a sus adjuntos para el inventario y la migración (T07 §9.2).</li><li>La cooperativa dispone de asesoría legal y contable para validar los parámetros con contenido jurídico y fiscal antes de su uso productivo.</li><li>El personal clave de la cooperativa (facturación, cobranza, contaduría, técnica) participará en el mapeo, las conciliaciones y la aprobación de la corrida paralela.</li><li>Los usuarios cuentan con conexión a Internet, salvo la aplicación de campo, que opera sin conexión y sincroniza al recuperarla.</li></ol><h3 id="_12-2-dependencias-externas" tabindex="-1">12.2 Dependencias externas <a class="header-anchor" href="#_12-2-dependencias-externas" aria-label="Permalink to &quot;12.2 Dependencias externas&quot;">​</a></h3><ol><li><strong>Convenios de la cooperativa con terceros</strong>: entes recaudadores, pasarelas de pago, bancos, proveedores de mensajería y operadores de red; el sistema se conecta, pero los convenios son de la cooperativa.</li><li><strong>Organismo fiscal</strong>: certificados de facturación electrónica de la cooperativa (la plataforma puede generar la solicitud de certificado, DEC-053) y disponibilidad de sus servicios.</li><li><strong>Proveedor de firma digital</strong>: debe elegirse antes de la ola O3 (DEC-078).</li><li><strong>Proveedores de mapas e inteligencia artificial</strong>: provistos por la plataforma, con opción de claves propias de la cooperativa (DEC-020).</li><li><strong>Reguladores</strong>: formatos de informes y resoluciones tarifarias vigentes en cada jurisdicción.</li><li><strong>Infraestructura en la nube</strong> en la región elegida (DEC-062).</li><li><strong>ProCoop</strong> como fuente de datos y como sistema de registro de los dominios no cortados durante la convivencia (DEC-068).</li></ol><hr><h2 id="_13-proximos-pasos-y-validaciones-pendientes" tabindex="-1">13. Próximos pasos y validaciones pendientes <a class="header-anchor" href="#_13-proximos-pasos-y-validaciones-pendientes" aria-label="Permalink to &quot;13. Próximos pasos y validaciones pendientes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>N.º</th><th>Próximo paso</th><th>Responsable sugerido</th></tr></thead><tbody><tr><td>1</td><td>Revisar y aprobar este resumen ejecutivo</td><td>Consejo y gerencia</td></tr><tr><td>2</td><td>Formalizar con Laguna Larga su participación como cooperativa piloto (DEC-088) y confirmar los servicios que presta y el orden de migración (PA-MIG-17)</td><td>Solicitante y conducción de la cooperativa</td></tr><tr><td>3</td><td>Validar con la asesoría legal los 8 parámetros con valor por defecto propuesto, los plazos de prescripción (DEC-052) y los plazos de conservación de datos (PA-NFR-06)</td><td>Asesoría legal y contable de la cooperativa</td></tr><tr><td>4</td><td>Revisar las decisiones asumidas de mayor impacto, empezando por las que afectan a las primeras olas</td><td>Solicitante con el equipo de análisis</td></tr><tr><td>5</td><td>Establecer la línea de base y las metas de los objetivos de impacto marcados &quot;a definir&quot; (sección 4.3)</td><td>Gerencia de la cooperativa piloto</td></tr><tr><td>6</td><td>Elegir el proveedor de firma digital antes de la ola O3 (DEC-078)</td><td>Solicitante</td></tr><tr><td>7</td><td>Confirmar los convenios vigentes con entes recaudadores, pasarelas y bancos de la cooperativa piloto</td><td>Tesorería de la cooperativa piloto</td></tr><tr><td>8</td><td>Elaborar el plan de validación con el cliente (artefacto 1.7), el plan de capacitación y gestión del cambio (artefacto 8.4), la estimación de esfuerzo por ola (artefacto 10.1) y el modelo de costos de operación (artefacto 10.3)</td><td>Equipo del proyecto</td></tr><tr><td>9</td><td>Iniciar la ola O0 y, en paralelo, el inventario y el diagnóstico de calidad de datos de la cooperativa piloto</td><td>Equipo del proyecto</td></tr></tbody></table><hr><h2 id="_14-documentos-de-referencia" tabindex="-1">14. Documentos de referencia <a class="header-anchor" href="#_14-documentos-de-referencia" aria-label="Permalink to &quot;14. Documentos de referencia&quot;">​</a></h2><p>Rutas relativas a esta carpeta (<code>docs/entregables-analisis-diseno/</code>).</p><table tabindex="0"><thead><tr><th>Documento</th><th>Ruta</th></tr></thead><tbody><tr><td>Índice de entregables de análisis y diseño</td><td><a href="./00-INDICE"><code>00-INDICE.md</code></a></td></tr><tr><td>Especificación maestra</td><td><a href="./../especificacion/00-ESPECIFICACION-MAESTRA"><code>../especificacion/00-ESPECIFICACION-MAESTRA.md</code></a></td></tr><tr><td>Registro de decisiones</td><td><a href="./../especificacion/01-registro-decisiones"><code>../especificacion/01-registro-decisiones.md</code></a></td></tr><tr><td>Preguntas abiertas</td><td><a href="./../especificacion/02-preguntas-abiertas"><code>../especificacion/02-preguntas-abiertas.md</code></a></td></tr><tr><td>Plan de olas y prompts</td><td><a href="./../especificacion/03-plan-de-olas-y-prompts"><code>../especificacion/03-plan-de-olas-y-prompts.md</code></a></td></tr><tr><td>Matriz de trazabilidad</td><td><a href="./../especificacion/04-matriz-trazabilidad"><code>../especificacion/04-matriz-trazabilidad.md</code></a></td></tr><tr><td>Registro de huecos</td><td><a href="./../especificacion/05-registro-huecos"><code>../especificacion/05-registro-huecos.md</code></a></td></tr><tr><td>Documento de alcance funcional</td><td><a href="./../alcance-funcional/GoodApps-Cooperativas-Alcance-Funcional"><code>../alcance-funcional/GoodApps-Cooperativas-Alcance-Funcional.md</code></a></td></tr><tr><td>T02 — Identidad, roles y auditoría</td><td><a href="./../especificacion/anexos/T02-IAM-identidad-roles-auditoria"><code>../especificacion/anexos/T02-IAM-identidad-roles-auditoria.md</code></a></td></tr><tr><td>T06 — Integraciones</td><td><a href="./../especificacion/anexos/T06-INT-integraciones"><code>../especificacion/anexos/T06-INT-integraciones.md</code></a></td></tr><tr><td>T07 — Migración desde ProCoop</td><td><a href="./../especificacion/anexos/T07-MIG-migracion-procoop"><code>../especificacion/anexos/T07-MIG-migracion-procoop.md</code></a></td></tr><tr><td>T08 — Requisitos no funcionales y seguridad</td><td><a href="./../especificacion/anexos/T08-NFR-no-funcionales-seguridad"><code>../especificacion/anexos/T08-NFR-no-funcionales-seguridad.md</code></a></td></tr><tr><td>T12 — Fichas verticales por servicio (partes 1 y 2)</td><td><a href="./../especificacion/anexos/T12-SRV-fichas-verticales-servicios-parte1"><code>../especificacion/anexos/T12-SRV-fichas-verticales-servicios-parte1.md</code></a> y <a href="./../especificacion/anexos/T12-SRV-fichas-verticales-servicios-parte2"><code>../especificacion/anexos/T12-SRV-fichas-verticales-servicios-parte2.md</code></a></td></tr></tbody></table>',39))])}const A=c(u,[["render",m]]);export{C as __pageData,A as default};
